        .kpi-card .context { font-size: 0.8em; color: #888; }

        table { width: 100%; border-collapse: collapse; margin: 20px 0; }
        th { background: #1e3a5f; color: white; padding: 12px; text-align: left; font-weight: 600; }
        td { padding: 12px; border-bottom: 1px solid #e9ecef; }
        tr:hover { background: #f8f9fa; }
        tr.highlight-row { background: #fff3cd; }

        .chart-container { margin: 25px 0; text-align: center; }
        .chart-container img { max-width: 100%; height: auto; border-radius: 8px; box-shadow: 0 2px 8px rgba(0,0,0,0.1); }
        .chart-caption { font-size: 0.9em; color: #666; margin-top: 10px; font-style: italic; }

        .findings-list { list-style: none; }
        .findings-list li { padding: 15px 0; border-bottom: 1px solid #e9ecef; }
        .findings-list li:last-child { border-bottom: none; }
        .finding-number { display: inline-block; background: #3d7bb8; color: white; width: 28px; height: 28px; border-radius: 50%; text-align: center; line-height: 28px; font-weight: bold; margin-right: 15px; }
        .finding-title { font-weight: 600; color: #1e3a5f; margin-bottom: 5px; }
        .finding-desc { color: #555; font-size: 0.95em; }

        .highlight-box { background: #e8f4f8; border-left: 4px solid #3d7bb8; padding: 20px; margin: 20px 0; border-radius: 4px; }
        .highlight-box.warning { background: #fef3cd; border-left-color: #ffc107; }
        .highlight-box.success { background: #d4edda; border-left-color: #28a745; }

        .footer { text-align: center; padding: 30px; color: #666; font-size: 0.85em; }

        .two-col { display: grid; grid-template-columns: 1fr 1fr; gap: 30px; }
        @media (max-width: 768px) { .two-col { grid-template-columns: 1fr; } }

